/** Paths `review(path)` would visit, sorted. Does not run checks. */
export function listReviewTargets(path: string, cwd: string = process.cwd()): string[] {
  if (isSkillDir(path)) {
    return [path, ...listCwdMemory(cwd)].sort((a, b) => a.localeCompare(b));
